def check_condition(date, governorate):
    # Assuming date and governorate are strings or JSON tuples
    if isinstance(date, str) and isinstance(governorate, str):
        # If both are strings, they refer to the same feature if they are equal
        return 1 if date == governorate else 0
    elif isinstance(date, dict) and isinstance(governorate, dict):
        # If both are JSON tuples (represented as dictionaries), they refer to the same feature if they have the same keys and values
        return 1 if date == governorate else 0
    else:
        # If one is a string and the other is a JSON tuple, they do not refer to the same feature
        return 0

